//
// # Safety
// `doc` is NULL or a document from this library; `out` and `starts` are NULL or writable.
ptrdiff_t gx_doc_ent_samples(const struct GxDoc *doc,
                             size_t e,
                             double *out,
                             size_t cap,
                             size_t *starts,
                             size_t cap_starts);

// Number of dimension slots. Removed dimensions leave empty slots.
